:root {
  --bg: #f4f5f9; --card: #fff; --text: #1a1a2e; --muted: #7a7a90;
  --border: #e0e0eb; --primary: #4f46e5; --ink: #fff;
  --accent: #eef0ff; --danger: #dc2626; --good: #16a34a;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
body { background: var(--bg); color: var(--text); font-family: 'Noto Sans Thai', 'Segoe UI', system-ui, sans-serif; min-height: 100vh; }
#app {
  max-width: 1500px;
  margin: 0 auto;
  padding: 24px;
}
h2 { font-size: 20px; font-weight: 700; }
.sub { color: var(--muted); font-size: 13px; margin-top: 4px; }
.card { background: var(--card); border: 1px solid var(--border); border-radius: 16px; padding: 20px; margin-bottom: 14px; }
.field { margin-bottom: 14px; }
label { display: block; font-size: 12px; color: var(--muted); font-weight: 700; margin-bottom: 6px; text-transform: uppercase; letter-spacing: .4px; }
input[type=text], input[type=password], input[type=number], select {
  width: 100%; padding: 10px 13px; border: 1.5px solid var(--border); border-radius: 10px;
  background: var(--bg); color: var(--text); font-size: 14px; outline: none; font-family: inherit;
}
input:focus, select:focus { border-color: var(--primary); }
.btn { display: inline-flex; align-items: center; gap: 6px; padding: 10px 18px; border-radius: 10px; font-size: 14px; font-weight: 600; cursor: pointer; border: none; font-family: inherit; transition: opacity .15s; }
.btn:hover { opacity: .88; }
.btn:disabled { opacity: .45; cursor: not-allowed; }
.btn-primary { background: var(--primary); color: var(--ink); }
.btn-outline { background: transparent; color: var(--primary); border: 1.5px solid var(--primary); }
.btn-danger  { background: transparent; color: var(--danger);  border: 1.5px solid var(--danger); }
.btn-good    { background: var(--good); color: #fff; }
.row  { display: flex; gap: 8px; flex-wrap: wrap; align-items: flex-end; }
.row > input, .row > select { flex: 1; min-width: 0; }
.tabs { display: flex; gap: 6px; margin-bottom: 18px; flex-wrap: wrap; }
.tab  { padding: 8px 16px; border-radius: 999px; border: 1.5px solid var(--border); cursor: pointer; font-size: 13px; color: var(--muted); background: transparent; font-family: inherit; }
.tab.on { background: var(--primary); color: var(--ink); border-color: var(--primary); }
.badge { display: inline-block; padding: 2px 10px; border-radius: 999px; font-size: 11px; font-weight: 700; }
.badge-admin { background: #fef3c7; color: #92400e; }
.badge-ev    { background: var(--accent); color: var(--primary); }
table { width: 100%; border-collapse: collapse; font-size: 13px; }
th, td { padding: 9px 7px; border-bottom: 1px solid var(--border); text-align: left; }
th { color: var(--muted); font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .4px; }
.muted { color: var(--muted); }
.dlnk { color: var(--danger); cursor: pointer; font-size: 13px; }
.lnk  { color: var(--primary); cursor: pointer; font-size: 13px; }
.list-row { display: flex; justify-content: space-between; align-items: center; padding: 10px 0; border-bottom: 1px solid var(--border); }
.list-row:last-child { border-bottom: none; }
.topbar { display: flex; justify-content: space-between; align-items: center; margin-bottom: 18px; }
.overflow { overflow-x: auto; }
.score-row { display: grid; grid-template-columns: 1fr 110px; gap: 10px; align-items: center; margin-bottom: 10px; }
.note { background: var(--accent); border-radius: 10px; padding: 13px 15px; font-size: 13px; color: var(--muted); }
.err  { background: #fef2f2; border: 1px solid #fecaca; border-radius: 10px; padding: 10px 14px; color: var(--danger); font-size: 13px; margin-bottom: 10px; }
.sep  { border: none; border-top: 1px solid var(--border); margin: 14px 0; }
.tag-max { font-size: 12px; color: var(--muted); }
/* Evaluator password list */
.ev-list { display: grid; gap: 8px; margin-top: 10px; }
.ev-item { display: grid; grid-template-columns: 1fr 120px 36px; gap: 8px; align-items: center; }
.ev-item span { font-size: 14px; font-weight: 500; }
.ev-item .pw  { font-size: 12px; color: var(--muted); font-family: monospace; background: var(--bg); padding: 4px 8px; border-radius: 6px; }

