/* ===== CINEMATIC WARP LOGIN TRANSITION ===== */
.warp-overlay {
  position:fixed; inset:0; z-index:99999; overflow:hidden;
  display:flex; align-items:center; justify-content:center;
  background:radial-gradient(ellipse at center,#123d78 0%,#071a38 42%,#020713 100%);
  animation:warp-in .28s ease-out both;
}
.warp-stars {
  position:absolute; inset:-50%;
  opacity:.55;
  background-image:radial-gradient(2px 2px at 20% 30%,#fff 98%,transparent),radial-gradient(1px 1px at 70% 20%,#72c8ff 98%,transparent),radial-gradient(2px 2px at 45% 75%,#fff 98%,transparent),radial-gradient(1px 1px at 85% 65%,#65aaff 98%,transparent),radial-gradient(1px 1px at 15% 85%,#fff 98%,transparent);
  background-size:230px 190px;
  animation:warp-stars 1.15s linear infinite;
}
.warp-ring {
  position:absolute; width:min(68vw,520px); aspect-ratio:1; border-radius:50%;
  border:2px solid rgba(80,174,255,.68);
  box-shadow:0 0 22px rgba(31,133,255,.55), inset 0 0 22px rgba(31,133,255,.25);
}
.warp-ring-a { animation:warp-ring 1s ease-in-out infinite; }
.warp-ring-b { width:min(48vw,360px); border-color:rgba(102,222,255,.5); animation:warp-ring 1s .18s ease-in-out infinite reverse; }
.warp-core {
  width:78px; height:78px; border-radius:50%; display:grid; place-items:center;
  color:#dff7ff; font-size:34px;
  background:radial-gradient(circle,#49c8ff 0%,#1769ce 42%,#09244d 75%);
  box-shadow:0 0 25px #269dff,0 0 85px rgba(24,135,255,.8);
  animation:warp-core .8s ease-in-out infinite alternate;
}
.warp-copy {
  position:absolute; top:calc(50% + 112px); display:flex; flex-direction:column;
  align-items:center; gap:7px; color:#eaf6ff; letter-spacing:2px;
  text-shadow:0 0 15px rgba(83,177,255,.7);
}
.warp-copy strong { font-size:14px; }
.warp-copy small { font-size:12px; color:#a8d6ff; letter-spacing:.5px; }
.warp-flash { position:absolute; inset:0; background:#dff7ff; opacity:0; pointer-events:none; animation:warp-flash .95s ease-out; }
.warp-overlay.warp-out { animation:warp-out .42s ease-in forwards; }
@keyframes warp-in { from{opacity:0} to{opacity:1} }
@keyframes warp-stars { from{transform:translateY(0) scale(1)} to{transform:translateY(130px) scale(1.35)} }
@keyframes warp-ring { 0%,100%{transform:scale(.72);opacity:.35} 50%{transform:scale(1.12);opacity:1} }
@keyframes warp-core { from{transform:scale(.85)} to{transform:scale(1.12)} }
@keyframes warp-flash { 0%,70%{opacity:0} 82%{opacity:.8} 100%{opacity:0} }
@keyframes warp-out { to{opacity:0; transform:scale(1.08); filter:blur(8px)} }
@media(prefers-reduced-motion:reduce) {
  .warp-overlay, .warp-stars, .warp-ring, .warp-core, .warp-flash { animation:none!important; }
}


