/* ===== IT LOGIN EXPERIENCE ===== */
.login-shell {
  width:min(900px,100%); min-height:500px; margin:clamp(24px,8vh,78px) auto;
  display:grid; grid-template-columns:1.02fr .98fr; overflow:hidden;
  border:1px solid rgba(194,219,249,.32); border-radius:24px;
  background:rgba(246,250,255,.96);
  box-shadow:0 28px 85px rgba(0,8,25,.42),0 0 0 1px rgba(255,255,255,.08);
}
.login-visual {
  position:relative; overflow:hidden; padding:36px;
  display:flex; flex-direction:column; justify-content:space-between;
  color:#f1f7ff;
  background:linear-gradient(145deg,rgba(7,24,53,.96),rgba(12,64,112,.94) 65%,rgba(7,35,72,.98));
}
.login-visual:before {
  content:""; position:absolute; inset:0; opacity:.22; pointer-events:none;
  background-image:linear-gradient(rgba(107,179,255,.22) 1px,transparent 1px),linear-gradient(90deg,rgba(107,179,255,.22) 1px,transparent 1px);
  background-size:34px 34px;
  mask-image:linear-gradient(135deg,#000,transparent 80%);
}
.login-chip,.login-symbol,.login-visual-copy,.login-visual-foot { position:relative; z-index:1; }
.login-chip {
  display:inline-flex; align-items:center; gap:9px; width:max-content;
  border:1px solid rgba(146,200,255,.24); border-radius:30px;
  padding:8px 12px; color:#b9dcff; font-size:10px; letter-spacing:1.3px;
  background:rgba(255,255,255,.06);
}
.chip-dot { width:7px;height:7px;border-radius:50%;background:#49d5ff;box-shadow:0 0 12px #49d5ff; }
.login-symbol {
  position:absolute; top:27%; right:12%; font-size:76px; font-weight:300;
  color:rgba(130,202,255,.24); text-shadow:0 0 35px rgba(57,157,255,.4);
}
.login-visual-copy { margin-top:auto; margin-bottom:auto; }
.login-kicker { color:#62c7ff!important; font-size:11px!important; letter-spacing:2.2px; font-weight:700; margin-bottom:12px!important; }
.login-visual-copy h1 { color:#fff; font-size:clamp(30px,4vw,43px); line-height:1.08; letter-spacing:1px; margin:0 0 18px; }
.login-visual-copy h1 span { color:#69caff; }
.login-visual-copy p:last-child { color:#b9cce2; font-size:13px; line-height:1.9; }
.login-visual-foot { display:flex; justify-content:space-between; color:#8eaccd; font-size:9px; letter-spacing:1.2px; }
.login-visual-foot span:last-child { color:#72e1bd; }
.login-orbit { position:absolute; border:1px solid rgba(88,177,255,.17); border-radius:50%; width:360px;height:360px;right:-170px;top:20%; }
.orbit-two { width:270px;height:270px;right:-125px;top:29%;border-color:rgba(88,177,255,.13); }
.login-form-panel { padding:48px 42px; display:flex; flex-direction:column; justify-content:center; }
.login-mini-mark { color:#2675d9; font-size:19px; font-weight:800; margin-bottom:38px; }
.login-mini-mark span { font-size:10px; letter-spacing:1.8px; color:#7b8fa9; margin-left:7px; }
.login-welcome { color:#3779c6; font-size:12px; font-weight:700; margin-bottom:5px; }
.login-form-panel h2 { color:#142b49; font-size:29px; margin:0 0 7px; }
.login-subtitle { color:#7d8da2; font-size:12px; line-height:1.7; margin-bottom:27px; }
.login-form-panel .field { margin-bottom:17px; }
.login-form-panel label { display:block; color:#415a78; font-size:12px; font-weight:700; margin-bottom:8px; }
.login-form-panel input,.login-form-panel select {
  width:100%; min-height:46px; border-radius:11px; background:#f7faff;
  border:1px solid #dce7f4; padding:0 13px; color:#203a59;
}
.login-form-panel input:focus,.login-form-panel select:focus {
  outline:none; border-color:#5e9ce9; box-shadow:0 0 0 3px rgba(42,117,217,.12); background:#fff;
}
.login-submit { width:100%; min-height:48px; display:flex; align-items:center; justify-content:space-between; padding:0 17px; border-radius:11px!important; margin-top:5px; }
.login-submit b { font-size:20px; font-weight:400; }
.login-secure { margin-top:25px; color:#8a9bb0; font-size:10px; text-align:center; }
.login-secure span { color:#3983d8; margin-right:5px; }
.warp-overlay {
  position:fixed; inset:0; z-index:99999; pointer-events:none; overflow:hidden;
  background:radial-gradient(ellipse at 50% 50%,rgba(77,177,255,.18),transparent 55%);
  opacity:0;
}
.swoosh-line {
  position:absolute; width:70vw; height:2px; top:50%; left:-75%;
  background:linear-gradient(90deg,transparent,rgba(134,218,255,.95),#fff,rgba(66,151,255,.9),transparent);
  box-shadow:0 0 18px 5px rgba(66,151,255,.55);
  transform:rotate(-8deg);
}
.swoosh-glow { position:absolute; inset:0; background:linear-gradient(110deg,transparent 38%,rgba(111,197,255,.13) 50%,transparent 62%); transform:translateX(-100%); }
.warp-overlay.warp-out { opacity:1; animation:swoosh-fade .22s ease-out forwards; }
.warp-overlay.warp-out .swoosh-line { animation:swoosh-pass .22s ease-out forwards; }
.warp-overlay.warp-out .swoosh-glow { animation:swoosh-pass .22s ease-out forwards; }
@keyframes swoosh-pass { to { transform:translateX(220%) rotate(-8deg); } }
@keyframes swoosh-fade { 0%{opacity:0} 35%{opacity:1} 100%{opacity:0} }
@media(max-width:720px) {
  .login-shell { grid-template-columns:1fr; margin:18px auto; border-radius:18px; }
  .login-visual { min-height:230px; padding:24px; }
  .login-visual-copy h1 { font-size:30px; }
  .login-symbol { top:20%; right:10%; font-size:55px; }
  .login-form-panel { padding:30px 24px; }
  .login-mini-mark { margin-bottom:22px; }
}
@media(prefers-reduced-motion:reduce) {
  .warp-overlay.warp-out,.warp-overlay.warp-out .swoosh-line,.warp-overlay.warp-out .swoosh-glow { animation:none!important; }
}
